// Lead lifecycle. A lead moves forward only; each workflow selects leads by
// status, so re-running a workflow never repeats completed work.

const STATUS = {
  // 01 Import & Validate
  VALIDATED: 'VALIDATED',
  INVALID: 'INVALID',
  DUPLICATE: 'DUPLICATE',
  SUPPRESSED: 'SUPPRESSED',
  COUNTRY_NOT_ENABLED: 'COUNTRY_NOT_ENABLED',
  SKIPPED_SOURCE_STATUS: 'SKIPPED_SOURCE_STATUS',
  // 02 Research
  RESEARCHED: 'RESEARCHED',
  MANUAL_REVIEW: 'MANUAL_REVIEW',
  // 03 Generate
  READY_FOR_APPROVAL: 'READY_FOR_APPROVAL',
  NO_RECOMMENDATION: 'NO_RECOMMENDATION',
  // 04 Send
  SENDING: 'SENDING',
  SENT: 'SENT',
  TEST_SENT: 'TEST_SENT',
  RETRY_PENDING: 'RETRY_PENDING',
  FAILED: 'FAILED',
  SEND_UNKNOWN: 'SEND_UNKNOWN',
  // 05 Inbox / 06 Unsubscribe
  REPLIED: 'REPLIED',
  UNSUBSCRIBED: 'UNSUBSCRIBED',
  BOUNCED: 'BOUNCED',
};

const APPROVAL = { PENDING: 'PENDING', APPROVED: 'APPROVED', REJECTED: 'REJECTED' };

const VALIDATION = { PASSED: 'PASSED', FAILED: 'FAILED' };

// Statuses after which a lead must never be contacted again automatically.
const TERMINAL_NO_CONTACT = new Set([
  STATUS.INVALID, STATUS.DUPLICATE, STATUS.SUPPRESSED, STATUS.SENT, STATUS.SEND_UNKNOWN,
  STATUS.FAILED, STATUS.REPLIED, STATUS.UNSUBSCRIBED, STATUS.BOUNCED, STATUS.SENDING,
]);

module.exports = { STATUS, APPROVAL, VALIDATION, TERMINAL_NO_CONTACT };

};
